const dictionaries: Record<Language, Messages> = { ca, en, es };

export function translate(language: Language, key: TranslationKey, values?: Record<string, string | number>): string {
  let message: string = dictionaries[language][key];
  if (values) {
    for (const [name, value] of Object.entries(values)) {
      message = message.replaceAll(`{${name}}`, String(value));
    }
  }
  return message;
}

export function translateError(language: Language, message: string): string {
  const errors: Partial<Record<string, TranslationKey>> = {
    'La anchura con espejos plegados no puede ser menor que la de la carrocería.': 'mirrorFoldedValidation',
    'La anchura con espejos desplegados no puede ser menor que la carrocería ni que con espejos plegados.': 'mirrorExtendedValidation',
    'La distancia entre ejes debe ser menor que la longitud.': 'wheelbaseValidation',
    'La bisagra y la longitud de cada puerta deben quedar dentro de la longitud del vehículo.': 'doorLengthValidation',
    'Introduce el fabricante.': 'manufacturerRequired',
    'Introduce el modelo.': 'modelRequired',
    'El año final debe ser igual o posterior al año inicial.': 'yearRangeValidation',
    'La salida no se ha calculado.': 'exitNotCalculated',
    'Introduce el diámetro de giro para usar el modelo bicicleta.': 'turningDiameterRequired',
    'No hay espacio para pasar la plaza antes de dar marcha atrás.': 'noSpaceBeforeReverse',
    'La búsqueda agotó los estados alcanzables sin encontrar una trayectoria.': 'searchExhausted',
    'IndexedDB no está disponible en este navegador.': 'indexedDbUnavailable',
    'No se pudo abrir la base de datos local.': 'databaseOpenError',
    'La base de datos local está bloqueada por otra pestaña.': 'databaseBlockedError',
    'Error al consultar datos locales.': 'databaseReadError',
    'La transacción local no pudo completarse.': 'databaseTransactionError',
    'La transacción local fue cancelada.': 'databaseAbortError',
  };
  const key = errors[message];
  if (key) return translate(language, key);

  const refinementSuffix = ' Se encontró al refinar la resolución de búsqueda.';
  if (message.endsWith(refinementSuffix)) {
    const baseReason = message.slice(0, -refinementSuffix.length);
    return `${translateError(language, baseReason)} ${translate(language, 'refinementFound')}`;
  }
  const budget = message.match(/^Límite de búsqueda alcanzado \(([\d.,]+) estados\); no se puede concluir que sea inaccesible\.$/);
  if (budget) return translate(language, 'searchLimitReached', { count: budget[1]! });
  const noPath = message.match(/^No se encontró una trayectoria con al menos ([\d.,]+) cm de holgura tras agotar la búsqueda gruesa y refinada \(([\d.,]+) cm, ([\d.,]+) cm\/([\d.,]+)°\)\.$/);
  if (noPath) {
    return translate(language, 'noPathAtResolution', {
      clearance: noPath[1]!, step: noPath[2]!, positionBin: noPath[3]!, angleBin: noPath[4]!,
    });
  }
  const approach = message.match(/^El vehículo no cabe con ([\d.,]+) cm de holgura en la zona de aproximación configurada\.$/);
  if (approach) return translate(language, 'vehicleClearanceApproach', { clearance: approach[1]! });
  const blocked = message.match(/^La posición final colisiona, no conserva la holgura mínima de ([\d.,]+) cm o sale del área modelada\.$/);
  if (blocked) return translate(language, 'targetPositionCollision', { clearance: blocked[1]! });
  const foundExit = message.match(/^Se encontró una salida (de culo|de frente)\.$/);
  if (foundExit) {
    return translate(language, 'exitFound', {
      mode: foundExit[1] === 'de culo' ? translate(language, 'reverseMode') : translate(language, 'forwardMode'),
    });
  }
  const noExit = message.match(/^No hay salida (de culo|de frente) en el modelo configurado \(el pasillo, los obstáculos o el radio de giro lo impiden\)\.$/);
  if (noExit) {
    return translate(language, 'exitNoPath', {
      mode: noExit[1] === 'de culo' ? translate(language, 'reverseMode') : translate(language, 'forwardMode'),
    });
  }
  const exitNotVerified = message.match(/^Salida (de culo|de frente) no verificada: (.*)$/);
  if (exitNotVerified) {
    return translate(language, 'exitNotVerifiedReason', {
      mode: exitNotVerified[1] === 'de culo' ? translate(language, 'reverseMode') : translate(language, 'forwardMode'),
      reason: translateError(language, exitNotVerified[2]!),
    });
  }
  const straight = message.match(/^Se encontró una trayectoria recta con al menos ([\d.,]+) cm de holgura frente a obstáculos\.$/);
  if (straight) return translate(language, 'straightTrajectory', { clearance: straight[1]! });
  const found = message.match(/^Se encontró una trayectoria con holgura mínima de ([\d.,]+) cm y tolerancia final de ([\d.,]+) cm y ([\d.,]+)°\.$/);
  if (found) {
    return translate(language, 'foundPathAtResolution', {
      clearance: found[1]!, positionTolerance: found[2]!, angleTolerance: found[3]!,
    });
  }
  const minimum = message.match(/^Too small: expected number to be >=([\d.,]+)$/);
  if (minimum) return translate(language, 'valueAtLeast', { minimum: minimum[1]! });
  const maximum = message.match(/^Too big: expected number to be <=([\d.,]+)$/);
  if (maximum) return translate(language, 'valueAtMost', { maximum: maximum[1]! });
  if (/^Invalid input: expected number, received (?:NaN|undefined)$/.test(message)) {
    return translate(language, 'invalidNumber');
  }
  return message;
}
